      story: `A boy named Minh stomped into his grandfather's kitchen, furious that his little sister had broken his paper boat. Grandfather said nothing. He filled the old iron kettle and set it on the stove.

"Watch the kettle," he said.

Minh crossed his arms. The kettle sat silent. Slowly, a whisper of steam rose. Then a soft hum. Only after a long while did it sing.

"You want me to calm down," Minh muttered.

"No," smiled Grandfather. "I want you to notice that even fire cannot rush water. It warms it, little by little, until the water is ready. Anger is the same. If you sit with it kindly, it changes on its own."

They drank tea together. By the second cup, Minh was already folding a new boat — with his sister.`,
